var ASMA_NOTE={ms:"Nabi ﷺ bersabda: Allah mempunyai 99 nama, sesiapa yang menghafal (memahami dan beramal dengannya) akan masuk syurga. Senarai nama di atas mengikut riwayat at-Tirmidhi.",en:"The Prophet ﷺ said: Allah has 99 names; whoever preserves them (learns and lives by them) will enter Paradise. The list above follows the narration in at-Tirmidhi.",src:"Sahih al-Bukhari 2736; Sahih Muslim 2677; Jami' at-Tirmidhi 3507"};

