HADITH_DAILY.push(
{"ms":"Ihsan ialah engkau menyembah Allah seolah-olah engkau melihat-Nya; jika tidak, Dia melihatmu.","en":"Ihsan is to worship Allah as though you see Him; and if you do not, He sees you.","src":"Al-Arba'in an-Nawawiyyah, no. 2","n40":2},
{"ms":"Islam dibina atas lima perkara: syahadah, solat, zakat, haji dan puasa Ramadan.","en":"Islam is built on five: the testimony, prayer, zakat, Hajj and fasting in Ramadan.","src":"Al-Arba'in an-Nawawiyyah, no. 3","n40":3},
{"ms":"Mohonlah pengakhiran yang baik; amalan dinilai pada penghujungnya.","en":"Ask Allah for a good ending; deeds are judged by how they end.","src":"Al-Arba'in an-Nawawiyyah, no. 4","n40":4},
{"ms":"Amalan yang tiada asalnya dalam agama akan ditolak.","en":"A deed that has no basis in the religion is rejected.","src":"Al-Arba'in an-Nawawiyyah, no. 5","n40":5},
{"ms":"Sesiapa yang menjauhi perkara syubhah telah memelihara agama dan maruahnya.","en":"Whoever avoids doubtful matters keeps their religion and honour safe.","src":"Al-Arba'in an-Nawawiyyah, no. 6","n40":6},
{"ms":"Apa yang dilarang, jauhilah. Apa yang diperintahkan, lakukan setakat mampu.","en":"Avoid what is forbidden, and do what is commanded as much as you can.","src":"Al-Arba'in an-Nawawiyyah, no. 9","n40":9},
{"ms":"Allah itu baik dan tidak menerima kecuali yang baik.","en":"Allah is good and accepts only what is good.","src":"Al-Arba'in an-Nawawiyyah, no. 10","n40":10},
{"ms":"Allah mewajibkan ihsan dalam segala sesuatu, hingga ketika menyembelih haiwan.","en":"Allah has prescribed excellence in everything, even when slaughtering an animal.","src":"Al-Arba'in an-Nawawiyyah, no. 17","n40":17},
{"ms":"Jika engkau tidak malu, lakukanlah apa sahaja yang engkau mahu.","en":"If you feel no shame, then do as you wish.","src":"Al-Arba'in an-Nawawiyyah, no. 20","n40":20},
{"ms":"Katakanlah: Aku beriman kepada Allah, kemudian istiqamahlah.","en":"Say: I believe in Allah, then stay firm.","src":"Al-Arba'in an-Nawawiyyah, no. 21","n40":21},
{"ms":"Tunaikan yang wajib, halalkan yang halal dan haramkan yang haram: itu jalan ke syurga.","en":"Do the obligations and keep to the halal and haram: that is the way to Paradise.","src":"Al-Arba'in an-Nawawiyyah, no. 22","n40":22},
{"ms":"Allah berfirman: Aku haramkan kezaliman atas diri-Ku dan Aku jadikannya haram di antara kamu.","en":"Allah says: I have forbidden injustice for Myself and made it forbidden among you.","src":"Al-Arba'in an-Nawawiyyah, no. 24","n40":24},
{"ms":"Setiap tasbih, takbir, tahmid dan tahlil adalah sedekah.","en":"Every tasbih, takbir, tahmid and tahlil is charity.","src":"Al-Arba'in an-Nawawiyyah, no. 25","n40":25},
{"ms":"Setiap langkah menuju solat adalah sedekah, dan membuang gangguan dari jalan adalah sedekah.","en":"Every step to the prayer is charity, and removing harm from the road is charity.","src":"Al-Arba'in an-Nawawiyyah, no. 26","n40":26},
{"ms":"Kebaikan ialah akhlak yang baik; dosa ialah apa yang meresahkan jiwamu.","en":"Righteousness is good character; sin is what unsettles your soul.","src":"Al-Arba'in an-Nawawiyyah, no. 27","n40":27},
{"ms":"Berpeganglah kepada sunnahku dan sunnah khulafa' ar-rasyidin.","en":"Hold to my Sunnah and the Sunnah of the rightly guided caliphs.","src":"Al-Arba'in an-Nawawiyyah, no. 28","n40":28},
{"ms":"Sedekah memadamkan dosa seperti air memadamkan api.","en":"Charity puts out sins as water puts out fire.","src":"Al-Arba'in an-Nawawiyyah, no. 29","n40":29},
{"ms":"Allah mendiamkan beberapa perkara sebagai rahmat, bukan kerana lupa.","en":"Allah was silent about some things out of mercy, not forgetfulness.","src":"Al-Arba'in an-Nawawiyyah, no. 30","n40":30},
{"ms":"Zuhudlah terhadap dunia nescaya Allah mengasihimu.","en":"Be detached from the world and Allah will love you.","src":"Al-Arba'in an-Nawawiyyah, no. 31","n40":31},
{"ms":"Tidak boleh memudaratkan dan tidak boleh membalas mudarat dengan mudarat.","en":"No harm, and no returning harm with harm.","src":"Al-Arba'in an-Nawawiyyah, no. 32","n40":32},
{"ms":"Sesiapa yang melihat kemungkaran, ubahlah dengan tangan, lidah atau hatinya.","en":"Whoever sees a wrong should change it with the hand, the tongue or the heart.","src":"Al-Arba'in an-Nawawiyyah, no. 34","n40":34},
{"ms":"Seorang Muslim ialah saudara Muslim yang lain: dia tidak menzalimi dan tidak menghinanya.","en":"A Muslim is a brother to a Muslim: he does not wrong him or look down on him.","src":"Al-Arba'in an-Nawawiyyah, no. 35","n40":35},
{"ms":"Niat melakukan kebaikan sudah ditulis sebagai satu kebaikan.","en":"Just intending a good deed is written as a good deed.","src":"Al-Arba'in an-Nawawiyyah, no. 37","n40":37},
{"ms":"Hamba-Ku sentiasa mendekatkan diri kepada-Ku dengan amalan sunat sehingga Aku mencintainya.","en":"My servant keeps drawing near to Me with voluntary deeds until I love him.","src":"Al-Arba'in an-Nawawiyyah, no. 38","n40":38},
{"ms":"Allah memaafkan umat ini atas kesilapan, lupa dan apa yang dipaksa.","en":"Allah has pardoned this nation's mistakes, forgetfulness and what they are forced to do.","src":"Al-Arba'in an-Nawawiyyah, no. 39","n40":39},
{"ms":"Jadilah engkau di dunia seperti orang asing atau orang yang sedang dalam perjalanan.","en":"Be in this world as though you are a stranger or a traveller.","src":"Al-Arba'in an-Nawawiyyah, no. 40","n40":40},
{"ms":"Tidak sempurna iman seseorang sehingga hawa nafsunya mengikut apa yang dibawa Nabi ﷺ.","en":"None truly believes until their desires follow what the Prophet ﷺ brought.","src":"Al-Arba'in an-Nawawiyyah, no. 41","n40":41},
{"ms":"Wahai anak Adam, selagi engkau berdoa dan berharap kepada-Ku, Aku ampunkan engkau.","en":"O son of Adam, as long as you call on Me and hope in Me, I will forgive you.","src":"Al-Arba'in an-Nawawiyyah, no. 42","n40":42}
);

