// Learn: readings in solat (Shafi'i, as commonly taught in Malaysia)
var BACAAN_SOLAT = [
{t_ms:"Niat (contoh: Zohor)",t_en:"Intention (example: Zohor)",ar:"أُصَلِّي فَرْضَ الظُّهْرِ أَرْبَعَ رَكَعَاتٍ مُسْتَقْبِلَ الْقِبْلَةِ أَدَاءً لِلَّهِ تَعَالَى",ms:"Sahaja aku solat fardu Zohor empat rakaat menghadap kiblat, tunai kerana Allah Taala.",en:"I intend to pray the obligatory Zohor, four rakaat, facing the Qibla, on time, for Allah the Exalted.",note_ms:"Niat ialah dalam hati ketika takbiratul ihram. Lafaz di lidah sebelum takbir disunatkan dalam mazhab Syafi'i untuk membantu hati.",note_en:"The intention is in the heart at the opening takbir. Saying it before the takbir is recommended in the Shafi'i school to help the heart.",src:"Sahih al-Bukhari 1"},
{t_ms:"Takbiratul ihram",t_en:"Opening takbir",ar:"اللَّهُ أَكْبَرُ",ms:"Allah Maha Besar",en:"Allah is the Greatest",src:"Sahih al-Bukhari 757"},
{t_ms:"Doa iftitah",t_en:"Opening supplication",ar:"اللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا. إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا مُسْلِمًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ. إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ، وَبِذَٰلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ",ms:"Allah Maha Besar dengan sebesar-besarnya, segala puji bagi Allah sebanyak-banyaknya, Maha Suci Allah pagi dan petang. Aku hadapkan wajahku kepada Tuhan yang mencipta langit dan bumi dalam keadaan lurus dan berserah diri, dan aku bukan daripada orang musyrik. Sesungguhnya solatku, ibadahku, hidupku dan matiku untuk Allah Tuhan sekalian alam, tiada sekutu bagi-Nya, dengan itu aku diperintahkan dan aku daripada orang Islam.",en:"Allah is the Greatest, greatly; much praise is for Allah; glory be to Allah morning and evening. I turn my face to the One who created the heavens and the earth, upright and submitting, and I am not of the polytheists. My prayer, my worship, my life and my death are for Allah, Lord of the worlds, with no partner. This I am commanded, and I am of the Muslims.",src:"Sahih Muslim 601; Sahih Muslim 771"},
{t_ms:"Al-Fatihah",t_en:"Al-Fatihah",ar:"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ. الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ. الرَّحْمَٰنِ الرَّحِيمِ. مَالِكِ يَوْمِ الدِّينِ. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ. اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ. صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ",ms:"Dengan nama Allah Yang Maha Pemurah lagi Maha Penyayang. Segala puji bagi Allah, Tuhan sekalian alam. Yang Maha Pemurah lagi Maha Penyayang. Yang menguasai hari pembalasan. Hanya Engkau yang kami sembah dan hanya kepada Engkau kami memohon pertolongan. Tunjukilah kami jalan yang lurus, jalan orang yang Engkau beri nikmat, bukan jalan mereka yang dimurkai dan bukan jalan mereka yang sesat.",en:"In the name of Allah, the Most Gracious, the Most Merciful. All praise is for Allah, Lord of the worlds, the Most Gracious, the Most Merciful, Master of the Day of Judgement. You alone we worship and You alone we ask for help. Guide us to the straight path, the path of those You have blessed, not of those who earned anger nor of those who went astray.",note_ms:"Rukun dalam setiap rakaat. Disunatkan menyebut Amin selepasnya.",note_en:"Obligatory in every rakaat. Say Amin after it.",src:"Al-Quran 1:1-7; Sahih al-Bukhari 756"},
{t_ms:"Surah pendek (contoh: Al-Ikhlas)",t_en:"A short surah (example: Al-Ikhlas)",ar:"قُلْ هُوَ اللَّهُ أَحَدٌ. اللَّهُ الصَّمَدُ. لَمْ يَلِدْ وَلَمْ يُولَدْ. وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ",ms:"Katakanlah: Dialah Allah Yang Maha Esa. Allah tempat bergantung. Dia tidak beranak dan tidak diperanakkan. Dan tiada sesuatu pun yang setara dengan-Nya.",en:"Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born, and there is none comparable to Him.",note_ms:"Sunat dalam rakaat pertama dan kedua.",note_en:"Sunnah in the first and second rakaat.",src:"Al-Quran 112:1-4"},
{t_ms:"Rukuk (3 kali)",t_en:"Bowing (3 times)",ar:"سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ",ms:"Maha Suci Tuhanku Yang Maha Agung dan dengan memuji-Nya",en:"Glory be to my Lord the Magnificent, and praise be to Him",src:"Sunan Abi Dawud 870"},
{t_ms:"Bangun dari rukuk & iktidal",t_en:"Rising from bowing",ar:"سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ",ms:"Allah mendengar orang yang memuji-Nya. Wahai Tuhan kami, bagi-Mu segala puji, sepenuh langit, sepenuh bumi dan sepenuh apa yang Engkau kehendaki selepas itu.",en:"Allah hears the one who praises Him. Our Lord, to You is all praise, filling the heavens, filling the earth and filling whatever else You will.",src:"Sahih Muslim 476"},
{t_ms:"Sujud (3 kali)",t_en:"Prostration (3 times)",ar:"سُبْحَانَ رَبِّيَ الْأَعْلَىٰ وَبِحَمْدِهِ",ms:"Maha Suci Tuhanku Yang Maha Tinggi dan dengan memuji-Nya",en:"Glory be to my Lord the Most High, and praise be to Him",src:"Sunan Abi Dawud 870"},
{t_ms:"Duduk antara dua sujud",t_en:"Sitting between the two prostrations",ar:"رَبِّ اغْفِرْ لِي وَارْحَمْنِي وَاجْبُرْنِي وَارْفَعْنِي وَارْزُقْنِي وَاهْدِنِي وَعَافِنِي وَاعْفُ عَنِّي",ms:"Tuhanku, ampunilah aku, rahmatilah aku, cukupkanlah kekuranganku, angkatlah darjatku, berilah aku rezeki, berilah aku petunjuk, sihatkanlah aku dan maafkanlah aku.",en:"My Lord, forgive me, have mercy on me, mend me, raise me, provide for me, guide me, keep me well and pardon me.",src:"Jami' at-Tirmidhi 284; Sunan Abi Dawud 850; Sunan Ibn Majah 898"},
{t_ms:"Qunut (rakaat kedua Subuh)",t_en:"Qunut (second rakaat of Subuh)",ar:"اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَىٰ عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ",ms:"Ya Allah, berilah aku petunjuk bersama orang yang Engkau beri petunjuk, sihatkanlah aku bersama orang yang Engkau sihatkan, peliharalah aku bersama orang yang Engkau pelihara, berkatilah apa yang Engkau berikan kepadaku, dan peliharalah aku daripada keburukan apa yang Engkau tetapkan. Sesungguhnya Engkau yang menetapkan dan tiada siapa menetapkan ke atas-Mu. Tidak hina orang yang Engkau lindungi dan tidak mulia orang yang Engkau musuhi. Maha Berkat Engkau wahai Tuhan kami dan Maha Tinggi.",en:"O Allah, guide me among those You have guided, keep me well among those You have kept well, take care of me among those You take care of, bless what You have given me, and protect me from the evil of what You have decreed. You decree and none decrees over You. Whoever You befriend is never humbled, and whoever You oppose is never honoured. Blessed are You, our Lord, and Exalted.",note_ms:"Dibaca selepas iktidal rakaat kedua Subuh dalam mazhab Syafi'i (sunat ab'adh). Jika tertinggal, sujud sahwi.",note_en:"Read after rising from bowing in the second rakaat of Subuh in the Shafi'i school. If missed, do sujud sahwi.",src:"Sunan Abi Dawud 1425; Jami' at-Tirmidhi 464"},
{t_ms:"Tahiyat awal",t_en:"First tashahhud",ar:"التَّحِيَّاتُ الْمُبَارَكَاتُ الصَّلَوَاتُ الطَّيِّبَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَىٰ عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ. اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ",ms:"Segala penghormatan, keberkatan, solat dan kebaikan adalah bagi Allah. Salam sejahtera ke atasmu wahai Nabi, serta rahmat Allah dan berkat-Nya. Salam sejahtera ke atas kami dan hamba-hamba Allah yang soleh. Aku bersaksi tiada tuhan melainkan Allah dan aku bersaksi bahawa Muhammad pesuruh Allah. Ya Allah, berselawatlah ke atas Muhammad.",en:"All greetings, blessings, prayers and good things are for Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god but Allah and that Muhammad is the Messenger of Allah. O Allah, send blessings upon Muhammad.",src:"Sahih Muslim 403"},
{t_ms:"Tahiyat akhir: selawat Ibrahimiyah",t_en:"Final tashahhud: Ibrahimi salawat",ar:"اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، وَبَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ",ms:"Ya Allah, berselawatlah ke atas Muhammad dan keluarga Muhammad sebagaimana Engkau berselawat ke atas Ibrahim dan keluarga Ibrahim, dan berkatilah Muhammad dan keluarga Muhammad sebagaimana Engkau memberkati Ibrahim dan keluarga Ibrahim. Di seluruh alam, sesungguhnya Engkau Maha Terpuji lagi Maha Mulia.",en:"O Allah, send blessings upon Muhammad and the family of Muhammad as You sent blessings upon Ibrahim and the family of Ibrahim, and bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim. In all the worlds, You are Praiseworthy, Glorious.",note_ms:"Dibaca selepas lafaz tahiyat (tanpa selawat ringkas di hujung tahiyat awal).",note_en:"Recited after the tashahhud words.",src:"Sahih Muslim 405"},
{t_ms:"Sebelum salam",t_en:"Before salam",ar:"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ",ms:"Ya Allah, aku berlindung kepada-Mu daripada azab neraka Jahannam, azab kubur, fitnah hidup dan mati, dan kejahatan fitnah Al-Masih Ad-Dajjal.",en:"O Allah, I seek refuge in You from the punishment of Hell, the punishment of the grave, the trials of life and death, and the evil of the trial of the False Messiah.",src:"Sahih Muslim 588"},
{t_ms:"Salam",t_en:"Salam",ar:"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ",ms:"Salam sejahtera ke atas kamu dan rahmat Allah",en:"Peace be upon you and the mercy of Allah",note_ms:"Ke kanan, kemudian ke kiri. Salam pertama adalah rukun.",note_en:"To the right, then to the left. The first salam is obligatory.",src:"Sahih Muslim 582"}
];

// Learn: solat hajat & istikharah guide
var GUIDE_SPECIAL = [
{id:"istikharah",t_ms:"Solat Istikharah",t_en:"Salat al-Istikharah",
 steps_ms:["Berwuduk dan pilih waktu yang tidak dilarang solat.","Niat solat sunat Istikharah 2 rakaat.","Rakaat pertama: Al-Fatihah dan Al-Kafirun (digalakkan). Rakaat kedua: Al-Fatihah dan Al-Ikhlas.","Selepas salam, puji Allah, berselawat, kemudian baca doa Istikharah dan sebut urusan anda di tempat 'urusan ini'.","Teruskan usaha. Petunjuk boleh datang melalui kecenderungan hati atau perjalanan urusan yang dipermudah. Boleh diulang."],
 steps_en:["Make wudhu and choose a time when prayer is not forbidden.","Intend 2 rakaat of Istikharah.","First rakaat: Al-Fatihah and Al-Kafirun (recommended). Second: Al-Fatihah and Al-Ikhlas.","After salam, praise Allah, send salawat, then recite the Istikharah doa and name your matter at 'this matter'.","Carry on with your effort. Guidance may come through ease in the matter or the heart's inclination. It may be repeated."],
 niat:"أُصَلِّي سُنَّةَ الِاسْتِخَارَةِ رَكْعَتَيْنِ لِلَّهِ تَعَالَى",niat_ms:"Sahaja aku solat sunat Istikharah dua rakaat kerana Allah Taala",niat_en:"I intend to pray two rakaat of Istikharah for Allah the Exalted",
 doa:"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَٰذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَٰذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ",
 doa_ms:"Ya Allah, aku memohon pilihan-Mu dengan ilmu-Mu, memohon kekuatan dengan kekuasaan-Mu, dan memohon kurnia-Mu yang agung. Engkau berkuasa sedangkan aku tidak, Engkau mengetahui sedangkan aku tidak, dan Engkau Maha Mengetahui perkara ghaib. Ya Allah, jika Engkau mengetahui urusan ini baik bagiku dalam agamaku, kehidupanku dan akibat urusanku, maka tetapkanlah ia bagiku, permudahkanlah, kemudian berkatilah bagiku. Jika Engkau mengetahui urusan ini buruk bagiku dalam agamaku, kehidupanku dan akibat urusanku, maka jauhkanlah ia daripadaku dan jauhkanlah aku daripadanya, tetapkanlah kebaikan bagiku di mana sahaja ia berada, kemudian jadikanlah aku reda dengannya.",
 doa_en:"O Allah, I seek Your guidance through Your knowledge, Your power through Your might, and I ask of Your great bounty. You are able and I am not; You know and I do not; You are the Knower of the unseen. O Allah, if You know this matter is good for me in my religion, my life and my end, then decree it for me, make it easy and bless it for me. If You know this matter is bad for me in my religion, my life and my end, then turn it away from me and turn me away from it, decree for me the good wherever it is, and make me content with it.",
 src:"Sahih al-Bukhari 1162"},
{id:"hajat",t_ms:"Solat Hajat",t_en:"Salat al-Hajat",
 steps_ms:["Berwuduk dengan sempurna.","Niat solat sunat Hajat 2 rakaat (boleh hingga 12 rakaat, 2 rakaat satu salam).","Baca Al-Fatihah dan mana-mana surah.","Selepas salam, puji Allah, berselawat ke atas Nabi ﷺ, kemudian baca doa Hajat dan mohon hajat anda dalam bahasa sendiri.","Yakin dengan Allah dan teruskan ikhtiar."],
 steps_en:["Make a complete wudhu.","Intend 2 rakaat of Hajat (up to 12, two per salam).","Recite Al-Fatihah and any surah.","After salam, praise Allah, send salawat on the Prophet ﷺ, then recite the Hajat doa and ask for your need in your own words.","Trust Allah and keep making effort."],
 niat:"أُصَلِّي سُنَّةَ الْحَاجَةِ رَكْعَتَيْنِ لِلَّهِ تَعَالَى",niat_ms:"Sahaja aku solat sunat Hajat dua rakaat kerana Allah Taala",niat_en:"I intend to pray two rakaat of Hajat for Allah the Exalted",
 doa:"لَا إِلَٰهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ، سُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ الْعَظِيمِ، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، لَا تَدَعْ لِي ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا حَاجَةً هِيَ لَكَ رِضًا إِلَّا قَضَيْتَهَا يَا أَرْحَمَ الرَّاحِمِينَ",
 doa_ms:"Tiada tuhan melainkan Allah Yang Maha Penyantun lagi Maha Pemurah. Maha Suci Allah, Tuhan Arasy yang agung. Segala puji bagi Allah, Tuhan sekalian alam. Aku memohon perkara yang mendatangkan rahmat-Mu, keampunan-Mu, keuntungan daripada setiap kebaikan dan keselamatan daripada setiap dosa. Janganlah Engkau biarkan dosaku melainkan Engkau ampunkan, kesusahan melainkan Engkau lapangkan, dan hajat yang Engkau redai melainkan Engkau tunaikan, wahai Yang Maha Penyayang.",
 doa_en:"There is no god but Allah, the Forbearing, the Generous. Glory be to Allah, Lord of the Mighty Throne. Praise be to Allah, Lord of the worlds. I ask You for what brings Your mercy and Your forgiveness, a share of every good and safety from every sin. Leave me no sin but that You forgive it, no worry but that You relieve it, and no need that pleases You but that You fulfil it, O Most Merciful of the merciful.",
 src:"Jami' at-Tirmidhi 479 [weak]; Sunan Ibn Majah 1384 [weak]"}
];

// Learn: solat for the sick (Shafi'i summary)
var SICK_GUIDE = {ms:["Solat tidak gugur selagi akal masih ada. Lakukan mengikut kemampuan.","Jika tidak mampu berdiri, solat secara duduk. Rukuk dengan membongkok sedikit, sujud lebih rendah daripada rukuk.","Jika tidak mampu duduk, solat berbaring mengiring ke kanan menghadap kiblat. Jika tidak mampu, terlentang dengan kaki ke arah kiblat dan kepala diangkat sedikit.","Jika tidak mampu bergerak, isyarat dengan kepala atau mata, dan lakukan rukun di dalam hati.","Jika air memudaratkan, bertayammum. Jika tidak mampu, minta bantuan orang lain.","Tanya doktor dan ustaz untuk keadaan khusus. Peringatan solat tetap berjalan dalam mod sakit."],
 en:["Prayer is not lifted while the mind is sound. Pray as you are able.","If you cannot stand, pray sitting. Bow by leaning forward a little and prostrate lower than the bow.","If you cannot sit, pray lying on your right side facing the Qibla. If not, lie on your back with feet towards the Qibla and head slightly raised.","If you cannot move, gesture with the head or eyes and perform the pillars in your heart.","If water would harm you, do tayammum. If you cannot, ask someone to help.","Ask a doctor and an ustaz about your own case. Prayer alerts keep running in sick mode."],
 src:"Sahih al-Bukhari 1117; Al-Quran 2:286"};

// Haid / nifas: what can still be done
var HAID_AMALAN = {ms:["Zikir: tasbih, tahmid, tahlil, takbir dan istighfar","Selawat ke atas Nabi ﷺ","Berdoa dalam apa jua bahasa","Wirid pagi dan petang (Al-Ma'thurat) dengan niat zikir","Mendengar bacaan Al-Quran dan kuliah ilmu","Bersedekah dan berbuat baik kepada orang lain","Menghafal Asmaul Husna"],
 en:["Zikir: tasbih, tahmid, tahlil, takbir and istighfar","Salawat on the Prophet ﷺ","Supplicate in any language","Morning and evening adhkar (Al-Ma'thurat) with the intention of zikir","Listen to Quran recitation and lessons","Give charity and do good to others","Learn the Asmaul Husna"],
 note_ms:"Dalam mazhab Syafi'i, wanita haid dan nifas tidak boleh solat, berpuasa, membaca Al-Quran dengan niat tilawah, menyentuh mushaf dan duduk di masjid. Solat yang ditinggalkan tidak perlu diqada, tetapi puasa wajib diganti.",
 note_en:"In the Shafi'i school, a woman in haid or nifas may not pray, fast, recite the Quran with the intention of recitation, touch the mushaf or stay in the masjid. Missed prayers are not made up, but missed fasts must be."};

// Musafir guide
var MUSAFIR = {ms:["Syarat (mazhab Syafi'i): perjalanan sekurang-kurangnya 2 marhalah (kira-kira 81 km, mengikut JAKIM), tujuannya harus (bukan maksiat), dan sudah keluar dari kawasan tempat tinggal.","Qasar: solat 4 rakaat (Zohor, Asar, Isyak) dipendekkan kepada 2 rakaat. Subuh dan Maghrib tidak boleh diqasar.","Jamak taqdim: Zohor dan Asar dalam waktu Zohor, atau Maghrib dan Isyak dalam waktu Maghrib. Mulakan dengan solat pertama dan jangan dipisahkan lama.","Jamak takhir: dalam waktu solat kedua. Niat jamak takhir mesti dibuat dalam waktu solat pertama.","Tempoh: jika berniat tinggal 4 hari atau lebih (selain hari tiba dan pulang), tidak lagi dikira musafir sebaik tiba.","Jika menjadi makmum kepada imam yang solat penuh, wajib solat penuh."],
 en:["Conditions (Shafi'i): a journey of at least 2 marhalah (about 81 km per JAKIM), for a permissible purpose, and you have left your hometown area.","Qasar: 4-rakaat prayers (Zohor, Asar, Isyak) are shortened to 2. Subuh and Maghrib are not shortened.","Jamak taqdim: Zohor and Asar in Zohor time, or Maghrib and Isyak in Maghrib time. Start with the first prayer and do not separate them for long.","Jamak takhir: in the time of the second prayer. The intention to delay must be made within the first prayer's time.","Duration: if you intend to stay 4 days or more (not counting arrival and departure days), you are no longer a traveller on arrival.","If you follow an imam who prays in full, you must pray in full."],
 src:"Al-Quran 4:101; Sahih Muslim 686; Sahih al-Bukhari 1107"};

