// Glossary of terms. key: [terms that link to it], ms, en
var GLOSSARY = [
{k:"marhalah",w:["marhalah"],ms:"Ukuran jarak perjalanan zaman dahulu. Dua marhalah kira-kira 81 km (JAKIM), jarak minimum untuk qasar dan jamak.",en:"An old unit of travel distance. Two marhalah is about 81 km (JAKIM), the minimum for shortening and combining prayers."},
{k:"istiwa",w:["istiwa'","istiwa"],ms:"Saat matahari tegak di atas kepala sebelum Zohor. Makruh solat sunat tanpa sebab pada waktu ini.",en:"The moment the sun is at its highest before Zohor. Sunnah prayer without a reason is disliked at this time."},
{k:"qada",w:["qada'","qada"],ms:"Menunaikan ibadah wajib (solat atau puasa) selepas waktunya berlalu.",en:"Making up an obligatory act of worship (prayer or fast) after its time has passed."},
{k:"sahwi",w:["sujud sahwi","sahwi"],ms:"Dua sujud sebelum salam kerana terlupa, contohnya tertinggal tahiyat awal atau qunut, atau ragu bilangan rakaat.",en:"Two prostrations before salam for forgetfulness, e.g. missing the first tashahhud or qunut, or doubt about the number of rakaat."},
{k:"tilawah",w:["sujud tilawah","tilawah"],ms:"Sujud sekali ketika membaca atau mendengar ayat sajdah.",en:"A single prostration when reciting or hearing a verse of prostration."},
{k:"jamak",w:["jamak"],ms:"Menghimpunkan dua solat dalam satu waktu: Zohor dengan Asar, Maghrib dengan Isyak.",en:"Combining two prayers in one time: Zohor with Asar, Maghrib with Isyak."},
{k:"qasar",w:["qasar"],ms:"Memendekkan solat 4 rakaat menjadi 2 rakaat ketika musafir.",en:"Shortening a 4-rakaat prayer to 2 while travelling."},
{k:"musafir",w:["musafir"],ms:"Orang yang dalam perjalanan jauh yang memenuhi syarat untuk mendapat rukhsah (keringanan).",en:"A traveller on a journey long enough to qualify for concessions."},
{k:"tumaninah",w:["tuma'ninah","tumaninah"],ms:"Berhenti seketika dalam setiap rukun sehingga anggota tenang. Ia rukun solat.",en:"Pausing in each position until the body is still. It is a pillar of prayer."},
{k:"iktidal",w:["iktidal"],ms:"Bangun berdiri tegak selepas rukuk.",en:"Standing up straight after bowing."},
{k:"iftitah",w:["iftitah"],ms:"Doa pembukaan selepas takbiratul ihram, sebelum Al-Fatihah.",en:"The opening supplication after the first takbir, before Al-Fatihah."},
{k:"takbiratulihram",w:["takbiratul ihram"],ms:"Takbir pertama yang memulakan solat. Ia rukun solat.",en:"The first takbir that begins the prayer. It is a pillar."},
{k:"tahiyat",w:["tahiyat"],ms:"Bacaan ketika duduk selepas rakaat kedua (awal) dan rakaat terakhir (akhir).",en:"The recitation while sitting after the second rakaat (first) and the last rakaat (final)."},
{k:"qunut",w:["qunut"],ms:"Doa selepas iktidal rakaat kedua Subuh (mazhab Syafi'i) dan dalam witir separuh akhir Ramadan.",en:"A supplication after rising from bowing in the second rakaat of Subuh (Shafi'i) and in witr in the second half of Ramadan."},
{k:"witir",w:["witir"],ms:"Solat sunat bilangan ganjil (1 hingga 11 rakaat) selepas Isyak, penutup solat malam.",en:"An odd-numbered sunnah prayer (1 to 11 rakaat) after Isyak, closing the night prayers."},
{k:"rawatib",w:["rawatib"],ms:"Solat sunat sebelum dan selepas solat fardu.",en:"Sunnah prayers before and after the obligatory prayers."},
{k:"tahajjud",w:["tahajjud","qiyamullail"],ms:"Solat sunat malam selepas tidur. Waktu terbaik ialah sepertiga malam terakhir.",en:"Night prayer after sleeping. The best time is the last third of the night."},
{k:"imsak",w:["imsak"],ms:"Waktu berjaga-jaga kira-kira 10 minit sebelum Subuh untuk berhenti makan sahur.",en:"A precaution time about 10 minutes before Subuh to stop eating sahur."},
{k:"syuruk",w:["syuruk"],ms:"Waktu matahari terbit. Waktu Subuh berakhir.",en:"Sunrise. The end of Subuh time."},
{k:"iqamah",w:["iqamah"],ms:"Seruan kedua sebelum solat berjemaah dimulakan.",en:"The second call just before congregational prayer starts."},
{k:"hadas",w:["hadas kecil","hadas besar","hadas"],ms:"Keadaan tidak suci. Hadas kecil diangkat dengan wuduk, hadas besar dengan mandi wajib.",en:"Ritual impurity. Minor impurity is lifted by wudhu, major by the obligatory bath."},
{k:"tayammum",w:["tayammum"],ms:"Bersuci dengan debu tanah apabila tiada air atau air memudaratkan.",en:"Purification with clean earth when there is no water or water would cause harm."},
{k:"haid",w:["haid"],ms:"Darah kebiasaan wanita setiap bulan. Tempoh minimum sehari semalam, maksimum 15 hari (Syafi'i).",en:"A woman's monthly period. At least a day and night, at most 15 days (Shafi'i)."},
{k:"nifas",w:["nifas"],ms:"Darah selepas bersalin. Biasanya 40 hari, maksimum 60 hari (Syafi'i).",en:"Post-natal bleeding. Usually 40 days, at most 60 days (Shafi'i)."},
{k:"junub",w:["junub","mandi wajib"],ms:"Hadas besar selepas hubungan suami isteri atau keluar mani. Diangkat dengan mandi wajib.",en:"Major impurity after intercourse or emission. Lifted by the obligatory bath."},
{k:"makruh",w:["makruh"],ms:"Perbuatan yang lebih baik ditinggalkan, tetapi tidak berdosa jika dilakukan.",en:"An act better avoided, but not sinful if done."},
{k:"muakkad",w:["muakkad"],ms:"Sunat yang sangat dituntut kerana Nabi ﷺ sentiasa melakukannya.",en:"A strongly emphasised sunnah that the Prophet ﷺ did regularly."},
{k:"ayyamulbidh",w:["ayyamul bidh"],ms:"13, 14 dan 15 haribulan Hijrah. Disunatkan berpuasa.",en:"The 13th, 14th and 15th of each Hijri month. Fasting is recommended."},
{k:"fidyah",w:["fidyah"],ms:"Bayaran secupak makanan asasi bagi setiap hari puasa yang ditinggalkan, untuk kes tertentu seperti uzur kekal.",en:"A payment of one portion of staple food per missed fast, in certain cases such as permanent inability."},
{k:"khusyuk",w:["khusyuk","khushu"],ms:"Hati yang hadir, tenang dan rendah diri di hadapan Allah ketika solat.",en:"A present, calm and humble heart before Allah in prayer."},
{k:"aurat",w:["aurat"],ms:"Bahagian tubuh yang wajib ditutup. Menutup aurat ialah syarat sah solat.",en:"The parts of the body that must be covered. Covering it is a condition of a valid prayer."},
{k:"mahram",w:["mahram"],ms:"Ahli keluarga yang haram dikahwini selama-lamanya, seperti ibu, ayah, adik-beradik.",en:"Close relatives one can never marry, such as parents and siblings."},
{k:"wirid",w:["wirid"],ms:"Zikir dan doa yang dibaca secara tetap, contohnya selepas solat.",en:"Zikir and doa read regularly, e.g. after prayers."},
{k:"rakaat",w:["rakaat"],ms:"Satu kitaran solat: berdiri, rukuk, iktidal, dua sujud.",en:"One cycle of prayer: standing, bowing, rising and two prostrations."},
{k:"lailatulqadar",w:["lailatul qadar"],ms:"Malam yang lebih baik daripada seribu bulan, pada 10 malam terakhir Ramadan.",en:"The night better than a thousand months, in the last 10 nights of Ramadan."},
{k:"tarawih",w:["tarawih"],ms:"Solat sunat malam di bulan Ramadan selepas Isyak.",en:"The night prayer of Ramadan after Isyak."}
];

// The 25 prophets named in the Quran (Malaysian list)
var NABI = [
{n:"Adam",ms:"Manusia dan nabi pertama, dicipta daripada tanah. Allah mengajarnya nama segala benda. Selepas tergelincir memakan buah larangan, baginda dan Hawa bertaubat dan Allah menerima taubat mereka.",en:"The first human and prophet, created from clay. Allah taught him the names of all things. After eating from the forbidden tree, he and Hawa repented and Allah forgave them.",l_ms:"Segera bertaubat apabila tersilap.",l_en:"Repent quickly when we make mistakes.",q:"2:30-37"},
{n:"Idris",ms:"Nabi yang tekun belajar dan dikatakan antara yang awal menulis dengan pena serta menjahit pakaian. Allah mengangkatnya ke tempat yang tinggi.",en:"A prophet devoted to learning, said to be among the first to write with a pen and sew clothes. Allah raised him to a high station.",l_ms:"Ilmu dan kerja yang baik adalah ibadah.",l_en:"Knowledge and good work are worship.",q:"19:56-57"},
{n:"Nuh",ms:"Berdakwah selama 950 tahun tetapi hanya sedikit yang beriman. Atas perintah Allah baginda membina bahtera, dan orang beriman serta haiwan diselamatkan daripada banjir besar.",en:"He called his people for 950 years but few believed. By Allah's command he built the ark, and the believers and animals were saved from the great flood.",l_ms:"Sabar dan tidak berputus asa dalam kebaikan.",l_en:"Be patient and never give up doing good.",q:"11:25-48; 29:14"},
{n:"Hud",ms:"Diutus kepada kaum 'Ad yang kuat dan membina bangunan tinggi tetapi sombong. Mereka dibinasakan oleh angin kencang selama tujuh malam lapan hari.",en:"Sent to the people of 'Ad, strong builders who grew arrogant. They were destroyed by a fierce wind for seven nights and eight days.",l_ms:"Kekuatan tidak berguna tanpa iman.",l_en:"Strength is worthless without faith.",q:"11:50-60; 69:6-7"},
{n:"Saleh",ms:"Diutus kepada kaum Thamud yang memahat rumah di gunung. Allah memberi mukjizat seekor unta betina, tetapi mereka menyembelihnya lalu dibinasakan dengan suara yang dahsyat.",en:"Sent to Thamud, who carved homes in mountains. Allah gave a she-camel as a sign, but they killed it and were destroyed by a mighty blast.",l_ms:"Hormati tanda-tanda Allah dan berlaku baik kepada haiwan.",l_en:"Respect Allah's signs and be kind to animals.",q:"11:61-68"},
{n:"Ibrahim",ms:"Kekasih Allah (Khalilullah). Menentang penyembahan berhala, dilempar ke dalam api tetapi api menjadi sejuk. Bersama Ismail membina Kaabah.",en:"The friend of Allah (Khalilullah). He rejected idols, was thrown into a fire that Allah made cool, and built the Kaabah with Ismail.",l_ms:"Yakin sepenuhnya kepada Allah.",l_en:"Trust Allah completely.",q:"21:51-70; 2:127"},
{n:"Lut",ms:"Anak saudara Nabi Ibrahim, diutus kepada kaum Sodom yang melakukan perbuatan keji. Baginda dan keluarga yang beriman diselamatkan, kecuali isterinya.",en:"Nephew of Ibrahim, sent to the people of Sodom who committed shameful acts. He and his believing family were saved, except his wife.",l_ms:"Berani menegur kemungkaran.",l_en:"Have courage to stand against wrongdoing.",q:"11:77-83"},
{n:"Ismail",ms:"Anak Nabi Ibrahim. Ketika bayi, air zamzam terpancar untuknya dan ibunya Hajar. Baginda reda ketika ayahnya diperintah untuk menyembelihnya, lalu Allah menggantikannya dengan seekor kibas.",en:"Son of Ibrahim. As a baby, Zamzam sprang up for him and his mother Hajar. He accepted when his father was commanded to sacrifice him, and Allah replaced him with a ram.",l_ms:"Taat kepada Allah dan ibu bapa.",l_en:"Obey Allah and your parents.",q:"37:100-107"},
{n:"Ishak",ms:"Anak Nabi Ibrahim dan Sarah, dilahirkan ketika ibu bapanya sudah tua sebagai khabar gembira daripada Allah. Keturunannya melahirkan ramai nabi.",en:"Son of Ibrahim and Sarah, born in their old age as glad tidings from Allah. Many prophets came from his descendants.",l_ms:"Tiada yang mustahil bagi Allah.",l_en:"Nothing is impossible for Allah.",q:"11:69-73"},
{n:"Yaakub",ms:"Anak Nabi Ishak, juga dikenali sebagai Israil. Baginda sangat sabar ketika kehilangan anaknya Yusuf selama bertahun-tahun.",en:"Son of Ishak, also called Israel. He showed beautiful patience when he lost his son Yusuf for many years.",l_ms:"Sabar yang indah dan tidak putus harapan.",l_en:"Beautiful patience and never losing hope.",q:"12:18, 83-87"},
{n:"Yusuf",ms:"Dibuang ke perigi oleh adik-beradiknya, dijual sebagai hamba, dipenjara kerana fitnah, kemudian menjadi menteri Mesir. Baginda memaafkan adik-beradiknya.",en:"Thrown into a well by his brothers, sold as a slave, jailed on a false charge, then became a minister of Egypt. He forgave his brothers.",l_ms:"Memaafkan dan menjaga maruah diri.",l_en:"Forgive, and guard your honour.",q:"Surah Yusuf (12)"},
{n:"Ayub",ms:"Diuji dengan kehilangan harta, anak-anak dan kesihatan selama bertahun-tahun, tetapi tetap bersabar dan bersyukur. Allah menyembuhkan dan menggantikan semuanya.",en:"Tested with loss of wealth, children and health for years, yet he stayed patient and grateful. Allah healed him and restored everything.",l_ms:"Sabar ketika sakit dan susah.",l_en:"Patience in sickness and hardship.",q:"21:83-84; 38:41-44"},
{n:"Syuaib",ms:"Diutus kepada penduduk Madyan yang menipu dalam timbangan dan sukatan. Baginda menyeru mereka berniaga dengan jujur.",en:"Sent to the people of Madyan who cheated in weights and measures. He called them to honest trade.",l_ms:"Jujur dalam jual beli.",l_en:"Be honest in trade.",q:"11:84-95"},
{n:"Musa",ms:"Diselamatkan ketika bayi di Sungai Nil dan dibesarkan di istana Firaun. Allah berkata-kata dengannya, memberinya Taurat, dan membelah laut untuk menyelamatkan Bani Israil.",en:"Saved as a baby on the Nile and raised in Pharaoh's palace. Allah spoke to him, gave him the Torah and parted the sea to save the Children of Israel.",l_ms:"Berani menegakkan kebenaran walaupun di hadapan orang zalim.",l_en:"Stand for the truth even before tyrants.",q:"20:9-79; 26:52-66"},
{n:"Harun",ms:"Abang Nabi Musa yang petah berbicara. Allah mengutusnya untuk membantu Musa berdakwah kepada Firaun.",en:"Musa's elder brother, an eloquent speaker. Allah sent him to help Musa call Pharaoh.",l_ms:"Saling membantu dalam kebaikan.",l_en:"Help one another in goodness.",q:"20:29-36"},
{n:"Zulkifli",ms:"Disebut dalam Al-Quran antara orang yang sabar dan terbaik. Baginda terkenal menepati janji dan adil dalam menghukum.",en:"Mentioned in the Quran among the patient and the best. Known for keeping promises and judging fairly.",l_ms:"Tepati janji.",l_en:"Keep your promises.",q:"21:85-86; 38:48"},
{n:"Daud",ms:"Mengalahkan Jalut ketika muda. Allah memberinya kitab Zabur, suara yang merdu, dan kepandaian melembutkan besi untuk membuat baju besi.",en:"Defeated Goliath when young. Allah gave him the Zabur, a beautiful voice and the skill to soften iron for armour.",l_ms:"Makan hasil usaha tangan sendiri.",l_en:"Eat from the work of your own hands.",q:"2:251; 34:10-11"},
{n:"Sulaiman",ms:"Anak Nabi Daud, raja yang memahami bahasa haiwan dan menguasai angin serta jin dengan izin Allah. Baginda sentiasa bersyukur.",en:"Son of Daud, a king who understood animals and commanded the wind and jinn by Allah's permission. He was always grateful.",l_ms:"Bersyukur atas setiap nikmat.",l_en:"Be grateful for every blessing.",q:"27:15-44"},
{n:"Ilyas",ms:"Diutus kepada kaum yang menyembah berhala bernama Ba'l. Baginda menyeru mereka kembali menyembah Allah Yang Esa.",en:"Sent to a people who worshipped the idol Baal. He called them back to Allah alone.",l_ms:"Hanya Allah yang layak disembah.",l_en:"Only Allah deserves worship.",q:"37:123-132"},
{n:"Ilyasa'",ms:"Pengganti Nabi Ilyas yang meneruskan dakwah kepada Bani Israil. Disebut dalam Al-Quran antara orang terbaik.",en:"Successor to Ilyas who continued calling the Children of Israel. Named in the Quran among the best.",l_ms:"Teruskan kerja baik orang sebelum kita.",l_en:"Carry on the good work of those before us.",q:"6:86; 38:48"},
{n:"Yunus",ms:"Meninggalkan kaumnya sebelum diizinkan, lalu ditelan ikan besar. Dalam gelap perut ikan, baginda berdoa: La ilaha illa anta subhanaka inni kuntu minaz zalimin. Allah menyelamatkannya.",en:"He left his people before being permitted and was swallowed by a great fish. In the darkness he prayed: La ilaha illa anta subhanaka inni kuntu minaz zalimin, and Allah saved him.",l_ms:"Berdoa dan mengaku salah ketika dalam kesusahan.",l_en:"Pray and admit your mistakes in hardship.",q:"21:87-88; 37:139-148"},
{n:"Zakaria",ms:"Penjaga Maryam. Ketika sudah tua dan isterinya mandul, baginda berdoa dengan lembut memohon anak, lalu Allah mengurniakan Yahya.",en:"Guardian of Maryam. Old, with a barren wife, he quietly asked Allah for a child and was given Yahya.",l_ms:"Jangan berhenti berdoa.",l_en:"Never stop making doa.",q:"19:2-11"},
{n:"Yahya",ms:"Anak Nabi Zakaria, diberi hikmah sejak kecil. Baginda sangat berbakti kepada ibu bapa dan tidak sombong.",en:"Son of Zakaria, given wisdom as a child. He was dutiful to his parents and never arrogant.",l_ms:"Berbakti kepada ibu bapa.",l_en:"Be dutiful to your parents.",q:"19:12-15"},
{n:"Isa",ms:"Dilahirkan oleh Maryam tanpa bapa. Berkata-kata ketika bayi, menyembuhkan orang buta dan sakit dengan izin Allah, dan diberi kitab Injil. Allah mengangkatnya ke langit.",en:"Born to Maryam without a father. He spoke as a baby, healed the blind and sick by Allah's permission and was given the Injil. Allah raised him up.",l_ms:"Rendah diri dan penyayang.",l_en:"Be humble and merciful.",q:"19:16-34; 4:157-158"},
{n:"Muhammad ﷺ",ms:"Nabi terakhir, lahir di Makkah. Menerima wahyu Al-Quran ketika berusia 40 tahun, berhijrah ke Madinah dan membawa rahmat untuk sekalian alam.",en:"The final Prophet, born in Makkah. He received the Quran at 40, migrated to Madinah and was sent as a mercy to all the worlds.",l_ms:"Ikuti akhlaknya yang mulia.",l_en:"Follow his noble character.",q:"33:40; 21:107; 68:4"}
];

