var DOA_SITUASI = {cat:"Situasi / Situations", items:[
{t_ms:"Ketika marah",t_en:"When angry",ar:"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ",ms:"Aku berlindung kepada Allah daripada syaitan yang direjam",en:"I seek refuge in Allah from the accursed devil",src:"Sahih al-Bukhari 3282; Sahih Muslim 2610"},
{t_ms:"Angin kencang",t_en:"Strong wind",ar:"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ",ms:"Ya Allah, aku memohon kebaikannya, kebaikan yang ada padanya dan kebaikan yang dibawanya, dan aku berlindung daripada keburukannya, keburukan yang ada padanya dan keburukan yang dibawanya",en:"O Allah, I ask You for its good, the good within it and the good it was sent with, and I seek refuge from its evil, the evil within it and the evil it was sent with",src:"Sahih Muslim 899"},
{t_ms:"Selepas hujan",t_en:"After rain",ar:"مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ",ms:"Kami diberi hujan dengan kurnia dan rahmat Allah",en:"We have been given rain by the grace and mercy of Allah",src:"Sahih al-Bukhari 846"},
{t_ms:"Takut atau terjaga malam",t_en:"Fear or waking at night",ar:"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ غَضَبِهِ وَعِقَابِهِ وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ",ms:"Aku berlindung dengan kalimah Allah yang sempurna daripada kemurkaan-Nya, azab-Nya, kejahatan hamba-hamba-Nya, bisikan syaitan dan kehadiran mereka",en:"I seek refuge in the perfect words of Allah from His anger, His punishment, the evil of His servants, the whispers of the devils and their presence",src:"Sunan Abi Dawud 3893; Jami' at-Tirmidhi 3528"},
{t_ms:"Melihat anak bulan",t_en:"Seeing the new moon",ar:"اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْيُمْنِ وَالْإِيمَانِ، وَالسَّلَامَةِ وَالْإِسْلَامِ، رَبِّي وَرَبُّكَ اللَّهُ",ms:"Ya Allah, terbitkanlah ia ke atas kami dengan keberkatan, iman, keselamatan dan Islam. Tuhanku dan Tuhanmu ialah Allah",en:"O Allah, bring it over us with blessing, faith, safety and Islam. My Lord and your Lord is Allah",src:"Jami' at-Tirmidhi 3451"},
{t_ms:"Melihat orang ditimpa musibah",t_en:"Seeing someone afflicted",ar:"الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَىٰ كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا",ms:"Segala puji bagi Allah yang menyelamatkan aku daripada apa yang menimpamu dan melebihkan aku atas ramai makhluk-Nya (dibaca perlahan)",en:"Praise be to Allah who spared me what He tested you with and favoured me over much of His creation (said quietly)",src:"Jami' at-Tirmidhi 3432"}
]};

