//        {k:"tbl", h:[ms,en], head:[[ms,en],...], rows:[[[ms,en],...],...]} table. count: rakaat for the counter button.
var GUIDE_MORE = {
  mandi: {parts:[
    {k:"p", t:["Mandi wajib (mandi junub) mesti dilakukan selepas berjunub (jimak atau keluar mani), selepas haid atau nifas berhenti, dan selepas bersalin. Tanpanya, solat, tawaf dan menyentuh mushaf tidak sah atau tidak dibenarkan.","The obligatory bath (ghusl) is required after janabah (intercourse or emission of mani), when haid or nifas ends, and after giving birth. Without it, solat and tawaf are not valid and touching the mushaf is not allowed."]},
    {k:"ul", h:["Rukun (wajib)","Obligatory parts"], li:[
      ["Niat ketika air mula terkena anggota badan.","Intention, made when the water first touches the body."],
      ["Meratakan air ke seluruh badan, kulit dan rambut, termasuk lipatan kulit.","Water reaching the whole body, skin and hair, including the folds of the skin."]]},
    {k:"ol", h:["Cara mandi wajib mengikut sunnah","How to do it, following the sunnah"], li:[
      ["Baca Bismillah dan berniat dalam hati ketika air pertama kali terkena badan.","Say Bismillah and make the intention in the heart as the water first touches the body."],
      ["Basuh kedua-dua tangan tiga kali.","Wash both hands three times."],
      ["Bersihkan kemaluan dan buang apa-apa najis.","Clean the private parts and remove any najis."],
      ["Berwuduk seperti untuk solat. Membasuh kaki boleh ditangguhkan hingga akhir.","Make wudhu as for solat. Washing the feet may be left until the end."],
      ["Curahkan air ke atas kepala tiga kali dan selati rambut dengan jari hingga ke pangkal.","Pour water over the head three times and run the fingers through the hair to the roots."],
      ["Basuh bahagian kanan badan, kemudian bahagian kiri.","Wash the right side of the body, then the left."],
      ["Pastikan air sampai ke ketiak, pusat, belakang telinga, celah jari tangan dan kaki.","Make sure water reaches the armpits, navel, behind the ears, and between the fingers and toes."]]},
    {k:"ar", h:["Niat mandi wajib","Intention for the obligatory bath"], ar:"نَوَيْتُ رَفْعَ الْحَدَثِ الْأَكْبَرِ لِلّٰهِ تَعَالَى", m:["Sahaja aku mengangkat hadas besar kerana Allah Taala.","I intend to lift the major ritual impurity for Allah the Exalted."]},
    {k:"ar", h:["Niat selepas haid","Intention after haid"], ar:"نَوَيْتُ رَفْعَ حَدَثِ الْحَيْضِ لِلّٰهِ تَعَالَى", m:["Sahaja aku mengangkat hadas haid kerana Allah Taala. Selepas nifas, sebut nifas.","I intend to lift the impurity of haid for Allah the Exalted. After nifas, say nifas instead."]},
    {k:"ar", h:["Dalil","Evidence"], ar:"وَإِن كُنتُمْ جُنُبًا فَاطَّهَّرُوا", m:["Dan jika kamu berjunub, maka bersucilah.","And if you are in a state of janabah, then purify yourselves."], src:"Al-Ma'idah 5:6"},
    {k:"ul", h:["Perlu tahu","Good to know"], li:[
      ["Wanita tidak perlu merungkai sanggul jika air sampai ke pangkal rambut (Sahih Muslim 330).","A woman need not undo her braids if the water reaches the roots of her hair (Sahih Muslim 330)."],
      ["Cara mandi Nabi ﷺ diceritakan oleh Aisyah (r.a.) dalam Sahih al-Bukhari 248.","The Prophet's ﷺ way of bathing is described by 'A'ishah (r.a.) in Sahih al-Bukhari 248."]]}
  ]},
  tayammum: {parts:[
    {k:"p", t:["Tayammum menggantikan wuduk atau mandi wajib dengan debu tanah yang bersih apabila air tidak dapat digunakan. Waktu solat mesti sudah masuk.","Tayammum replaces wudhu or the obligatory bath with clean dust when water cannot be used. The prayer time must already have started."]},
    {k:"ul", h:["Bila dibenarkan","When it is allowed"], li:[
      ["Tiada air selepas dicari.","There is no water after searching for it."],
      ["Sakit atau luka yang akan bertambah teruk jika terkena air.","An illness or wound that water would make worse."],
      ["Air yang ada diperlukan untuk minum.","The water you have is needed for drinking."]]},
    {k:"ol", h:["Cara bertayammum","How to do it"], li:[
      ["Sediakan debu tanah yang bersih. Tanggalkan cincin.","Find clean dust. Take off any rings."],
      ["Berniat ketika tapak tangan pertama kali menyentuh debu, dan kekalkan niat hingga menyapu muka.","Make the intention as the palms first touch the dust, and keep it until you wipe the face."],
      ["Tepukan pertama: letak kedua-dua tapak tangan pada debu, kemudian sapu seluruh muka.","First strike: place both palms on the dust, then wipe the whole face."],
      ["Tepukan kedua: letak tapak tangan pada debu sekali lagi dengan jari direnggangkan.","Second strike: place the palms on the dust again with the fingers spread."],
      ["Sapu tangan kanan hingga ke siku dengan tangan kiri, kemudian tangan kiri dengan tangan kanan.","Wipe the right arm up to the elbow with the left hand, then the left arm with the right hand."],
      ["Ikut tertib seperti di atas.","Keep this order."]]},
    {k:"ar", h:["Niat tayammum","Intention for tayammum"], ar:"نَوَيْتُ التَّيَمُّمَ لِاسْتِبَاحَةِ فَرْضِ الصَّلَاةِ لِلّٰهِ تَعَالَى", m:["Sahaja aku bertayammum untuk mengharuskan solat fardu kerana Allah Taala.","I intend tayammum to make the obligatory prayer permissible, for Allah the Exalted."]},
    {k:"ar", h:["Dalil","Evidence"], ar:"فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ", m:["Lalu kamu tidak mendapat air, maka bertayammumlah dengan tanah yang bersih; sapulah muka dan tangan kamu.","And you find no water, then do tayammum with clean earth and wipe your faces and hands."], src:"An-Nisa' 4:43"},
    {k:"ul", h:["Perlu tahu","Good to know"], li:[
      ["Satu tayammum untuk satu solat fardu, tetapi boleh diikuti beberapa solat sunat.","One tayammum covers one obligatory prayer, and may be followed by several sunnah prayers."],
      ["Batal dengan perkara yang membatalkan wuduk, dan dengan melihat air sebelum solat jika sebabnya ialah ketiadaan air.","It is broken by whatever breaks wudhu, and by finding water before the prayer if the reason was having no water."]]}
  ]},
  istinja: {parts:[
    {k:"p", t:["Istinjak ialah membersihkan diri selepas buang air. Najis pula ada tiga jenis, dan setiap satu ada cara membersihkannya sendiri.","Istinja' is cleaning yourself after using the toilet. Najis comes in three kinds, and each has its own way of being cleaned."]},
    {k:"ar", h:["Doa masuk tandas (masuk dengan kaki kiri)","Doa on entering the toilet (left foot first)"], ar:"اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ", m:["Ya Allah, aku berlindung dengan-Mu daripada syaitan lelaki dan syaitan perempuan.","O Allah, I seek refuge in You from the male and female devils."], src:"Sahih al-Bukhari 142"},
    {k:"ol", h:["Cara beristinjak","How to do istinja'"], li:[
      ["Jangan menghadap atau membelakangi kiblat di kawasan terbuka. Di dalam bangunan yang berdinding, ia dibenarkan.","Do not face or turn your back to the Qibla in the open. Inside a walled building it is allowed."],
      ["Gunakan tangan kiri.","Use the left hand."],
      ["Basuh dengan air hingga najis hilang.","Wash with water until the najis is gone."],
      ["Atau gunakan batu atau tisu sekurang-kurangnya tiga kali sapuan hingga bersih, dengan bilangan ganjil, selagi najis belum kering dan tidak merebak.","Or use stones or tissue, at least three wipes until clean and an odd number, as long as the najis has not dried or spread."],
      ["Paling baik: tisu dahulu, kemudian air.","Best of all: tissue first, then water."],
      ["Keluar dengan kaki kanan dan baca doa keluar tandas.","Leave with the right foot and read the doa for leaving."]]},
    {k:"ar", h:["Doa keluar tandas","Doa on leaving the toilet"], ar:"غُفْرَانَكَ", m:["Aku memohon keampunan-Mu.","I ask Your forgiveness."], src:"Sunan Abi Dawud 30"},
    {k:"tbl", h:["Tiga jenis najis","The three kinds of najis"], head:[["Jenis","Kind"],["Contoh","Examples"],["Cara membersihkan","How to clean it"]], rows:[
      [["Mughallazah (berat)","Mughallazah (heavy)"],["Anjing, babi","Dog, pig"],["Basuh 7 kali, salah satunya dengan air bercampur tanah (Sahih Muslim 279)","Wash 7 times, one of them with water mixed with clean soil (Sahih Muslim 279)"]],
      [["Mutawassitah (sederhana)","Mutawassitah (medium)"],["Air kencing, tahi, darah, muntah, arak","Urine, faeces, blood, vomit, alcoholic drink"],["Basuh hingga hilang warna, bau dan rasa","Wash until the colour, smell and taste are gone"]],
      [["Mukhaffafah (ringan)","Mukhaffafah (light)"],["Air kencing bayi lelaki bawah 2 tahun yang hanya minum susu","Urine of a baby boy under 2 who only drinks milk"],["Renjis air hingga basah merata","Sprinkle water until the area is wet all over"]]]}
  ]},
  jenazah: {parts:[
    {k:"p", t:["Solat jenazah ialah fardu kifayah: jika sebahagian orang Islam melakukannya, yang lain terlepas daripada dosa. Ia dilakukan berdiri dengan empat takbir, tanpa rukuk dan sujud, dan diakhiri dengan salam.","The funeral prayer is a communal obligation (fardu kifayah): if some Muslims do it, the rest are free of sin. It is prayed standing with four takbir, with no rukuk or sujud, and ends with salam."]},
    {k:"ol", h:["Cara solat jenazah","How to pray"], li:[
      ["Berdiri dan berniat. Imam berdiri setentang kepala jenazah lelaki, dan setentang punggung jenazah perempuan.","Stand and make the intention. The imam stands level with the head of a male body, and level with the middle of a female body."],
      ["Takbir pertama, kemudian baca Al-Fatihah.","First takbir, then recite Al-Fatihah."],
      ["Takbir kedua, kemudian baca selawat ke atas Nabi ﷺ (selawat Ibrahimiyah).","Second takbir, then send blessings on the Prophet ﷺ (the Ibrahimiyah salawat)."],
      ["Takbir ketiga, kemudian berdoa untuk jenazah.","Third takbir, then pray for the deceased."],
      ["Takbir keempat, kemudian berdoa untuk jenazah dan diri kita.","Fourth takbir, then pray for the deceased and for ourselves."],
      ["Beri salam ke kanan, kemudian ke kiri.","Give salam to the right, then to the left."]]},
    {k:"ar", h:["Niat (jenazah lelaki)","Intention (male)"], ar:"أُصَلِّي عَلَى هٰذَا الْمَيِّتِ أَرْبَعَ تَكْبِيرَاتٍ فَرْضَ كِفَايَةٍ لِلّٰهِ تَعَالَى", m:["Sahaja aku solat ke atas jenazah ini empat takbir, fardu kifayah kerana Allah Taala.","I intend to pray over this deceased with four takbir, as a communal obligation, for Allah the Exalted."]},
    {k:"ar", h:["Niat (jenazah perempuan)","Intention (female)"], ar:"أُصَلِّي عَلَى هٰذِهِ الْمَيِّتَةِ أَرْبَعَ تَكْبِيرَاتٍ فَرْضَ كِفَايَةٍ لِلّٰهِ تَعَالَى", m:["Sahaja aku solat ke atas jenazah perempuan ini empat takbir, fardu kifayah kerana Allah Taala.","I intend to pray over this deceased woman with four takbir, as a communal obligation, for Allah the Exalted."]},
    {k:"ar", h:["Selepas takbir ketiga","After the third takbir"], ar:"اللّٰهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ", m:["Ya Allah, ampunilah dia, rahmatilah dia, sejahterakanlah dia dan maafkanlah dia. Untuk jenazah perempuan: lahā, warḥamhā, wa'āfihā, wa'fu 'anhā.","O Allah, forgive him, have mercy on him, keep him safe and pardon him. For a woman: lahā, warḥamhā, wa'āfihā, wa'fu 'anhā."], src:"Sahih Muslim 963"},
    {k:"ar", h:["Selepas takbir keempat","After the fourth takbir"], ar:"اللّٰهُمَّ لَا تَحْرِمْنَا أَجْرَهُ وَلَا تُضِلَّنَا بَعْدَهُ", m:["Ya Allah, janganlah Engkau halang kami daripada pahalanya, dan janganlah Engkau sesatkan kami selepas pemergiannya. Ramai di Malaysia menambah: wa lā taftinnā ba'dahu waghfir lanā wa lahu.","O Allah, do not deprive us of his reward, and do not let us go astray after him. Many in Malaysia add: wa lā taftinnā ba'dahu waghfir lanā wa lahu."], src:"Sunan Abi Dawud 3201"}
  ]},
  raya: {count:2, parts:[
    {k:"p", t:["Solat Hari Raya ialah sunat muakkad, dua rakaat, selepas matahari naik hingga sebelum gelincir. Khutbah dibaca selepas solat.","The Eid prayer is a strongly recommended sunnah of two rakaat, from after sunrise until just before midday. The khutbah comes after the prayer."]},
    {k:"ol", h:["Cara solat","How to pray"], li:[
      ["Niat, takbiratul ihram, kemudian doa iftitah.","Intention, opening takbir, then the opening doa."],
      ["Rakaat pertama: tujuh takbir sebelum Al-Fatihah, mengangkat tangan setiap kali, dengan zikir di antara takbir.","First rakaat: seven takbir before Al-Fatihah, raising the hands each time, with the dhikr between them."],
      ["Baca Al-Fatihah dan surah. Sunat: Qaf atau Al-A'la.","Recite Al-Fatihah and a surah. Sunnah: Qaf or Al-A'la."],
      ["Rakaat kedua: selepas bangun, lima takbir lagi sebelum Al-Fatihah. Sunat: Al-Qamar atau Al-Ghasyiyah.","Second rakaat: after rising, five more takbir before Al-Fatihah. Sunnah: Al-Qamar or Al-Ghashiyah."],
      ["Selesaikan seperti solat dua rakaat biasa, kemudian dengar khutbah.","Finish like any two-rakaat prayer, then listen to the khutbah."],
      ["Jika terlupa takbir tambahan, solat tetap sah. Jangan berpatah balik.","If you forget the extra takbir, the prayer is still valid. Do not go back for them."]]},
    {k:"ar", h:["Niat Aidilfitri","Intention for Eid al-Fitr"], ar:"أُصَلِّي سُنَّةَ عِيدِ الْفِطْرِ رَكْعَتَيْنِ لِلّٰهِ تَعَالَى", m:["Sahaja aku solat sunat Hari Raya Aidilfitri dua rakaat kerana Allah Taala.","I intend to pray the sunnah of Eid al-Fitr, two rakaat, for Allah the Exalted."]},
    {k:"ar", h:["Niat Aidiladha","Intention for Eid al-Adha"], ar:"أُصَلِّي سُنَّةَ عِيدِ الْأَضْحَى رَكْعَتَيْنِ لِلّٰهِ تَعَالَى", m:["Sahaja aku solat sunat Hari Raya Aidiladha dua rakaat kerana Allah Taala.","I intend to pray the sunnah of Eid al-Adha, two rakaat, for Allah the Exalted."]},
    {k:"ar", h:["Zikir di antara takbir","Dhikr between the takbir"], ar:"سُبْحَانَ اللّٰهِ، وَالْحَمْدُ لِلّٰهِ، وَلَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ", m:["Maha Suci Allah, segala puji bagi Allah, tiada tuhan melainkan Allah, Allah Maha Besar.","Glory be to Allah, all praise is for Allah, there is no god but Allah, Allah is the Greatest."]},
    {k:"ul", h:["Sunnah hari raya","Sunnah of the day"], li:[
      ["Aidilfitri: makan beberapa biji kurma, bilangan ganjil, sebelum keluar solat (Sahih al-Bukhari 953).","Eid al-Fitr: eat a few dates, an odd number, before going out to pray (Sahih al-Bukhari 953)."],
      ["Aidiladha: tangguhkan makan hingga selepas solat.","Eid al-Adha: wait to eat until after the prayer."],
      ["Pergi melalui satu jalan dan pulang melalui jalan lain (Sahih al-Bukhari 986).","Go by one route and come back by another (Sahih al-Bukhari 986)."],
      ["Tujuh dan lima takbir: Jami' at-Tirmidhi 536.","Seven and five takbir: Jami' at-Tirmidhi 536."]]}
  ]},
  gerhana: {count:2, parts:[
    {k:"p", t:["Solat gerhana ialah sunat muakkad ketika gerhana matahari (kusuf) atau gerhana bulan (khusuf), dari mula hingga gerhana berakhir. Cara paling sempurna dalam mazhab Syafi'i: dua rakaat, setiap rakaat dengan dua kali berdiri dan dua kali rukuk, diikuti khutbah. Paling ringkas: dua rakaat seperti solat sunat biasa.","The eclipse prayer is a strongly recommended sunnah during a solar (kusuf) or lunar (khusuf) eclipse, from its start until it clears. The most complete way in the Shafi'i school: two rakaat, each with two standings and two rukuk, followed by a khutbah. The simplest way: two rakaat like any sunnah prayer."]},
    {k:"ol", h:["Cara yang sempurna","The complete way"], li:[
      ["Niat, takbiratul ihram dan doa iftitah.","Intention, opening takbir and the opening doa."],
      ["Baca Al-Fatihah dan surah yang panjang.","Recite Al-Fatihah and a long surah."],
      ["Rukuk lama, kemudian bangun, tetapi jangan sujud. Baca Al-Fatihah dan surah sekali lagi, lebih pendek.","A long rukuk, then rise, but do not go down to sujud. Recite Al-Fatihah and a surah again, a little shorter."],
      ["Rukuk kali kedua, bangun iktidal, kemudian dua sujud seperti biasa.","A second rukuk, rise, then two sujud as usual."],
      ["Rakaat kedua sama: dua kali berdiri, dua kali rukuk, kemudian sujud, tahiyat dan salam.","The second rakaat is the same: two standings, two rukuk, then sujud, tashahhud and salam."],
      ["Perbanyakkan zikir, doa, istighfar dan sedekah hingga gerhana berakhir.","Increase dhikr, doa, seeking forgiveness and charity until the eclipse ends."]]},
    {k:"ar", h:["Niat gerhana matahari","Intention, solar eclipse"], ar:"أُصَلِّي سُنَّةَ الْكُسُوفِ رَكْعَتَيْنِ لِلّٰهِ تَعَالَى", m:["Sahaja aku solat sunat gerhana matahari dua rakaat kerana Allah Taala.","I intend to pray the sunnah of the solar eclipse, two rakaat, for Allah the Exalted."]},
    {k:"ar", h:["Niat gerhana bulan","Intention, lunar eclipse"], ar:"أُصَلِّي سُنَّةَ الْخُسُوفِ رَكْعَتَيْنِ لِلّٰهِ تَعَالَى", m:["Sahaja aku solat sunat gerhana bulan dua rakaat kerana Allah Taala.","I intend to pray the sunnah of the lunar eclipse, two rakaat, for Allah the Exalted."]},
    {k:"ul", h:["Dalil","Evidence"], li:[
      ["Nabi ﷺ bersabda bahawa matahari dan bulan ialah dua tanda kebesaran Allah. Apabila melihat gerhana, berdoalah, bertakbir, solat dan bersedekah (Sahih al-Bukhari 1044).","The Prophet ﷺ said the sun and moon are two of Allah's signs. When you see an eclipse, make doa, say takbir, pray and give charity (Sahih al-Bukhari 1044)."],
      ["Kaunter rakaat mengira sujud, jadi rukuk tambahan tidak mengganggu kiraan.","The rakaat counter counts sujud, so the extra rukuk does not upset the count."]]}
  ]}
};
